7	/**
8	 * Runs in the create-owner pipeline after {@link RequireOwnerFields}: normalizes the telephone by
9	 * removing every non-digit character, then requires exactly 10 digits. The normalized 10-digit value
10	 * is written back onto the (shared) {@link OwnerFieldsDto} so {@link BuildOwner} maps and stores it,
11	 * and it is what {@code GET /owners/{id}} later returns. A value that is not exactly 10 digits after
12	 * stripping is rejected with a 400 by {@code InvalidTelephoneExceptionHandler}.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    public void service(@Val OwnerFieldsDto owner) throws InvalidTelephoneException {
17	        String digits = TelephoneNormalizer.normalize(owner.getTelephone());
18	        if (digits.length() != 10) {
19	            throw new InvalidTelephoneException(digits);
20	        }
21	        owner.setTelephone(digits);
22	    }
23	}
