1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Runs after {@link NormalizeOwnerTelephone} in the create-owner pipeline: rejects the request with a
11	 * 409 (via {@code DuplicateTelephoneExceptionHandler}) when the normalized telephone is already used by
12	 * any other owner. Comparison strips every non-digit character from both sides so an owner stored with
13	 * differently formatted digits still counts as a match. The new owner is not persisted yet, so every
14	 * match found is another owner.
15	 */
16	public class RequireUniqueTelephone {
17	
18	    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
19	            throws DuplicateTelephoneException {
20	        // NormalizeOwnerTelephone already ran, so this is a normalized 10-digit value. Stored owners
21	        // are normalized through the same shared rule for owners created outside this pipeline.
22	        String digits = owner.getTelephone();
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (digits.equals(TelephoneNormalizer.normalize(existing.getTelephone()))) {
25	                throw new DuplicateTelephoneException(digits);
26	            }
27	        }
28	    }
29	}
