4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
6	
7	/**
8	 * Normalizes the optional owner {@code email}: a blank (absent) value is left as-is, a present value
9	 * must be a syntactically valid address and is stored lower-cased. The normalized value is written back
10	 * onto the (shared) {@link OwnerFieldsDto} so {@link BuildOwner}/{@link ApplyOwner} store it and
11	 * {@code GET /owners/{id}} later returns it. A present-but-invalid value is rejected with a 400 by
12	 * {@code InvalidEmailExceptionHandler}.
13	 */
14	public class NormalizeOwnerEmail {
15	
16	    public void service(@Val OwnerFieldsDto owner) throws InvalidEmailException {
17	        String email = owner.getEmail();
18	        if (EmailNormalizer.isBlank(email)) {
19	            return;
20	        }
21	        if (!EmailNormalizer.isValid(email)) {
22	            throw new InvalidEmailException(email);
23	        }
24	        owner.setEmail(EmailNormalizer.normalize(email));
25	    }
26	}
